<?php
namespace WPKit\SiteDoctor\Scanners; use WPKit\SiteDoctor\{SiteDoctorIssue,SiteDoctorScanner}; if(!defined('ABSPATH'))exit;
final class WordPressScanner implements SiteDoctorScanner{public function id():string{return 'technical';}public function label():string{return 'WordPress Configuration';}public function scan():array{$o=[];$v=get_bloginfo('version');$php=PHP_VERSION;if(version_compare($php,'8.0','<'))$o[]=$this->i('old-php','technical','medium','manual_only','PHP version is older than 8.0','The server is running PHP '.$php.'.','Plan an upgrade with your host after compatibility testing.');if(!get_option('permalink_structure'))$o[]=$this->i('plain-permalinks','technical','low','safe','Plain permalinks are enabled','The site is using the default plain permalink structure.','Consider a readable permalink structure for a public website.');if(!get_option('blogdescription'))$o[]=$this->i('missing-tagline','technical','info','safe','Site tagline is empty','The WordPress tagline is empty.','Add a concise site description if it is useful for your branding or metadata.');return $o;}private function i($id,$c,$s,$r,$t,$d,$rec){return new SiteDoctorIssue(['id'=>$id,'category'=>$c,'severity'=>$s,'risk'=>$r,'title'=>$t,'description'=>$d,'recommendation'=>$rec]);}}
